+/// Normalizes one co-Z odd-multiple chain of `base` with a single inversion.
+///
+/// The chain starts at `Z = 2 * Y * Z_base`, so the inverse of the base `Z`
+/// is `2 * Y` times the inverse of that `Z`.
+fn normalize_co_z_chain(
+    base: ProjectivePoint,
+    table: &[ProjectivePoint; 8],
+    factors: &[FieldElement; 8],
+) -> [AffinePoint; 8] {
+    let Some(mut z_inverse) = table[7].z.invert() else {
+        return batch_normalize(*table);
+    };
+    let mut out = [AffinePoint::IDENTITY; 8];
+
+    for k in (1..8).rev() {
+        let z_inverse2 = z_inverse.square();
+        out[k] = AffinePoint {
+            x: table[k].x * z_inverse2,
+            y: table[k].y * z_inverse2 * z_inverse,
+            infinity: false,
+        };
+        z_inverse = z_inverse * factors[k];
+    }
+
+    let z_inverse = z_inverse * double(base.y);
+    let z_inverse2 = z_inverse.square();
+    out[0] = AffinePoint {
+        x: base.x * z_inverse2,
+        y: base.y * z_inverse2 * z_inverse,
+        infinity: false,
+    };
+
+    out
+}
