+fn shl_limbs(a: [u64; 4], n: u32) -> [u64; 4] {
+    [
+        a[0] << n,
+        (a[1] << n) | (a[0] >> (64 - n)),
+        (a[2] << n) | (a[1] >> (64 - n)),
+        (a[3] << n) | (a[2] >> (64 - n)),
+    ]
+}
